sp_widget.client_script:
api.controller = function($scope, spUtil) {

    var c = this;

    c.sendSOS = function() {

        if(confirm("Are you sure you want to send an Emergency SOS Alert?")) {

            spUtil.addInfoMessage(
                "Emergency SOS Alert sent successfully."
            );

            c.server.get({
                action: "sos"
            }).then(function(response){

            });

        }

    };

};

sp_widget.css:
.tm-sos-widget{
    background:#fff;
    border-radius:14px;
    padding:16px;
    border:1px solid #e5e7eb;
    box-shadow:0 6px 18px rgba(0,0,0,0.08);
    max-width:320px;
    margin:auto;
    text-align:center;
    transition:all .3s ease;
}

.tm-sos-widget:hover{
    transform:translateY(-2px);
    box-shadow:0 10px 24px rgba(0,0,0,0.12);
}

/* Header */

.tm-sos-header{
    margin-bottom:12px;
}

.tm-sos-header i{
    display:block;
    font-size:28px;
    color:#dc2626;
    margin-bottom:6px;
}

.tm-sos-header h3{
    margin:0;
    font-size:18px;
    font-weight:700;
    color:#1e293b;
}

/* Status Badge */

.tm-status{
    display:inline-flex;
    align-items:center;
    gap:8px;
    background:#fef2f2;
    color:#dc2626;
    padding:8px 14px;
    border-radius:50px;
    font-size:12px;
    font-weight:600;
    margin-bottom:12px;
}

.pulse{
    width:10px;
    height:10px;
    border-radius:50%;
    background:#dc2626;
    animation:pulse 1.5s infinite;
}

@keyframes pulse{
    0%{
        transform:scale(1);
        opacity:1;
    }

    100%{
        transform:scale(2);
        opacity:0;
    }
}

/* Date Time */

.tm-time{
    font-size:12px;
    color:#64748b;
    margin-bottom:15px;
}

/* SOS Button */

.tm-sos-btn{
    width:100%;
    border:none;
    background:linear-gradient(135deg,#ef4444,#dc2626);
    color:#fff;
    padding:12px;
    border-radius:10px;
    font-size:14px;
    font-weight:700;
    cursor:pointer;
    transition:all .3s ease;
}

.tm-sos-btn:hover{
    transform:translateY(-2px);
    box-shadow:0 8px 18px rgba(220,38,38,.35);
}

/* Contact Section */

.tm-contact-info{
    margin-top:15px;
}

/* Contact Cards */

.contact-card{
    display:flex;
    align-items:center;
    gap:10px;
    padding:10px;
    margin-bottom:8px;
    border-radius:10px;
    background:#f8fafc;
    text-align:left;
    border:1px solid #e2e8f0;
}

.contact-card:last-child{
    margin-bottom:0;
}

.contact-card i{
    width:35px;
    height:35px;
    display:flex;
    align-items:center;
    justify-content:center;
    background:#fee2e2;
    color:#dc2626;
    border-radius:50%;
    font-size:14px;
    flex-shrink:0;
}

.contact-card label{
    display:block;
    font-size:11px;
    color:#64748b;
    margin-bottom:2px;
    font-weight:500;
}

.contact-card strong{
    display:block;
    font-size:13px;
    color:#1e293b;
    font-weight:600;
}

/* Mobile */

@media (max-width:768px){

    .tm-sos-widget{
        max-width:100%;
        padding:14px;
    }

    .tm-sos-header h3{
        font-size:16px;
    }

    .tm-sos-btn{
        font-size:13px;
        padding:10px;
    }
}

sp_widget.script:
(function() {

